INSERT INTO `cursos` VALUES (5,4,'Curso Completo de Java','Aprende Java desde cero hasta ProgramaciÃ³n Orientada a Objetos. Tipos de datos, estructuras de control, excepciones, colecciones y POO completo.','40',1,'2026-08-03 11:37:24','2026-08-03 11:52:30'),(6,3,'Curso Completo de Python','Domina Python desde lo bÃ¡sico hasta programaciÃ³n avanzada. Aprende sintaxis, funciones, orientaciÃ³n a objetos, manejo de archivos y librerÃ­as populares.','40',1,'2026-08-03 11:56:43','2026-08-03 11:56:43'),(7,7,'Curso Completo de MySQL','Aprende MySQL desde SQL bÃ¡sico hasta optimizaciÃ³n. Domina consultas, Ã­ndices, procedimientos almacenados y mejores prÃ¡cticas de bases de datos.','35',1,'2026-08-03 11:56:43','2026-08-03 11:56:43'),(8,NULL,'Curso Completo de HTML y CSS','Aprende HTML y CSS desde cero. Domina la estructura web, estilos, layouts modernos y diseÃ±o responsive para crear sitios web profesionales.','30',1,'2026-08-03 11:57:39','2026-08-03 11:57:39'),(9,NULL,'Curso Completo de JavaScript','Domina JavaScript desde variables y funciones hasta conceptos avanzados. Aprende a crear aplicaciones web interactivas y dinÃ¡micas.','40',1,'2026-08-03 11:57:39','2026-08-03 11:57:39'),(10,13,'Curso Completo de C#','Domina C# desde lo bÃƒÂ¡sico hasta programaciÃƒÂ³n avanzada. Aprende .NET, LINQ, async/await y construcciÃƒÂ³n de aplicaciones robustas.','45',1,'2026-08-03 12:04:52','2026-08-03 12:45:03');
