  SELECT i.id, i.usuario_id, i.curso_id, c.titulo, c.emoji, i.fecha_inscripcion, i.leccion_actual, i.activo
  FROM inscripciones i
  INNER JOIN usuarios u ON i.usuario_id = u.id
